actions.script:
import org.moqui.resource.ResourceReference

List results = []
List searchPaths = [
    "component://agi-ide/resources/screen/archetype",
    "component://agi-ai/mcp/resources/screen/archetype"
]

searchPaths.each { basePath ->
    try {
        ResourceReference dirRef = ec.resource.getLocationReference(basePath)
        if (dirRef != null && dirRef.getExists() && dirRef.isDirectory()) {
            dirRef.directoryEntries.each { entry ->
                if (entry.fileName.endsWith(".xml")) {
                    String rawName = entry.fileName.replace(".xml", "")
                    results.add([
                        name: rawName,
                        uri: entry.location,
                        description: "Canonical ${rawName} screen archetype layout"
                    ])
                }
            }
        }
    } catch (Exception ignore) {}
}

context.archetypes = results
